-- sandhyavandanam / Abhivadanam
update public.pooja_steps set
  mantra_sanskrit = 'अभिवादये [PRAVARA_RISHIS]
[ARSHEYA] प्रवरान्वित [GOTRA] गोत्रः आपस्तम्ब सूत्रः
यजुः शाखाऽध्यायी श्री [NAME] शर्मा नामाहं अस्मि भोः',
  mantra_tamil = 'அபிவாதயே [PRAVARA_RISHIS]
[ARSHEYA] ப்ரவராந்வித [GOTRA] கோத்ர꞉ ஆபஸ்தம்ப ஸூத்ர꞉
யஜு꞉ ஶாகாத்யாயீ ஶ்ரீ [NAME] ஶர்மா நாமாஹம் அஸ்மி போ꞉',
  mantra_translit = 'abhivādaye [PRAVARA_RISHIS]
[ARSHEYA] pravarānvita [GOTRA] gotraḥ āpastamba sūtraḥ
yajuḥ śākhā''dhyāyī śrī [NAME] śarmā nāmāhaṃ asmi bhoḥ',
  instruction_en = 'Cover both ears with the hands and recite, then touch the floor at the end. Your pravara rishis, gotra and name are filled in from the gotra you chose before beginning.',
  instruction_ta = 'இரு காதுகளையும் கைகளால் மூடிச் சொல்லி, இறுதியில் தரையைத் தொடவும். தொடங்கும் முன் நீங்கள் தேர்ந்தெடுத்த கோத்ரத்திலிருந்து உங்கள் ப்ரவர ரிஷிகள், கோத்ரம், பெயர் நிரப்பப்பட்டுள்ளன.',
  philosophy_en = 'The one sentence in the rite that is about the reciter rather than the deity: the rishis of the lineage, the gotra, the Apastamba sutra and the Yajus recension, and finally one''s own name. The ears are covered because one''s own name and lineage are about to be said aloud.',
  source_ref = 'Yajurveda Trikaala Sandhyaavandanam (Giri), p.43; gotra and pravara filled from the tables, pp.65-80',
  updated_at = now()
 where pooja_id = 'sandhyavandanam' and step_title_en = 'Abhivadanam';

-- sandhyavandanam / Samarpanam
update public.pooja_steps set
  mantra_sanskrit = 'अभिवादये [PRAVARA_RISHIS]
[ARSHEYA] प्रवरान्वित [GOTRA] गोत्रः आपस्तम्ब सूत्रः
यजुः शाखाऽध्यायी श्री [NAME] शर्मा नामाहं अस्मि भोः
कायेन वाचा मनसेन्द्रियैर्वा बुध्याऽऽत्मना वा प्रकृतेः स्वभावात्।
करोमि यद्यत् सकलं परस्मै नारायणायेति समर्पयामि॥
मन्त्रहीनं क्रियाहीनं भक्तिहीनं जनार्दन।
यत् कृतं तु मया देव परिपूर्णं तदस्तु ते॥
प्रायश्चित्तान्यशेषाणि तपःकर्मात्मकानि वै।
यानि तेषामशेषाणां श्री कृष्णानुस्मरणं परम्॥
